acceptance_cmd:
set -x; set -u; f=0
grep -qE "^[[:space:]]*kg_install_signal_traps [a-z_]" ops/ios_test.sh || { echo "PC1 ios_test.sh wiring line not found -- cwd or regex broken, not the fix"; f=1; }
grep -qE "^cleanup\(\)" ops/ios_test.sh || { echo "PC2 ios_test.sh cleanup() not at column 0 -- the NOFN probe below cannot discriminate"; f=1; }
( cd ops/tests && bash -c 'source ../kg_reconcile.sh >/dev/null 2>&1; type -t paths_need_deploy' ) >/dev/null 2>&1 || { echo "PC3 kg_reconcile.sh is no longer sourceable from another script -- resolve the lib via \${BASH_SOURCE[0]}, not \$0; this breaks ops/tests/test_kg_reconcile.sh:307 and ops/release.sh:693"; f=1; }
grep -qE "^kg_install_signal_traps\(\)" ops/lib/signal_traps.sh 2>/dev/null || { echo "NOLIB ops/lib/signal_traps.sh does not define kg_install_signal_traps()"; f=1; }
[ ! -e ops/lib/ios_signal_traps.sh ] || { echo "OLDLIB ops/lib/ios_signal_traps.sh still present"; f=1; }
for s in ops/ios_test.sh ops/kg_reconcile.sh devops.sh ops/backup_verify.sh; do
  bash -n "$s" || { echo "SYNTAX $s"; f=1; }
  grep -qE "^[^#]*lib/signal_traps\.sh" "$s" || { echo "NOSOURCE $s"; f=1; }
  fn=$(sed -n 's/^[[:space:]]*kg_install_signal_traps \([a-z_][a-z0-9_]*\).*/\1/p' "$s" | head -1)
  if [ -z "$fn" ]; then echo "NOWIRE $s"; f=1;
  elif ! grep -qE "^${fn}\(\)" "$s"; then echo "NOFN $s wires ${fn} but never defines ${fn}()"; f=1; fi
  if grep -qE "^[^#]*trap[^#]*EXIT INT TERM" "$s"; then echo "OLDSHAPE $s"; f=1; fi
done
exit $f
